import paradox.music.nativeui.*;import android.app.*;import android.os.*;import java.io.*;import java.nio.file.*;
public class EarlyCrashHarness{public static void main(String[]a)throws Exception{Application app=new Application();app.getFilesDir().mkdirs();File report=new File(app.getFilesDir(),"ultra-music-crash.txt");int[] calls={0};Thread.setDefaultUncaughtExceptionHandler((t,e)->calls[0]++);NativeMusicDiagnostics.install(app);if(a[0].equals("capture")){Thread.getDefaultUncaughtExceptionHandler().uncaughtException(Thread.currentThread(),new IllegalStateException("SYNTHETIC_BEFORE_MUSIC_TAP"));if(!new String(Files.readAllBytes(report.toPath())).contains("SYNTHETIC_BEFORE_MUSIC_TAP")||calls[0]!=1)throw new AssertionError();NativeMusicDiagnostics.recoveryNote("later stale task");if(!new String(Files.readAllBytes(report.toPath())).contains("SYNTHETIC_BEFORE_MUSIC_TAP"))throw new AssertionError("Original crash overwritten");System.out.println("PASS pre-Music crash persisted, prior handler delegated, recovery preserves original exception");}else{app.listener.onActivityResumed(new Activity());for(int i=0;i<100&&AlertDialog.view==null;i++){Thread.sleep(10);Handler.drain();}if(AlertDialog.view==null||!AlertDialog.view.view.text.contains("SYNTHETIC_BEFORE_MUSIC_TAP")||!report.exists())throw new AssertionError("Report not retained across next launch");AlertDialog.copy.onClick(null,0);if(!android.content.ClipboardManager.copied.contains("SYNTHETIC_BEFORE_MUSIC_TAP"))throw new AssertionError();System.out.println("PASS next-process report appears and stays on disk until Copy acknowledgement");}System.exit(0);}}
